type Listener = (payload: any) => void;

export class EventBus {
    private listeners: Map<string, Listener[]> = new Map();

    subscribe(event: string, callback: Listener) {
        if (!this.listeners.has(event)) {
            this.listeners.set(event, []);
        }
        this.listeners.get(event)!.push(callback);
    }

    publish(event: string, payload: any) {
        if (this.listeners.has(event)) {
            this.listeners.get(event)!.forEach(callback => {
                try {
                    callback(payload);
                } catch (e) {
                    console.error(`Error in event bus callback for event ${event}:`, e);
                }
            });
        }
    }
}

export const eventBus = new EventBus();

import { randomUUID } from 'crypto';

export interface User {
    id: string;
    name: string;
    email: string;
}

class UserService {
    private userStore: Map<string, User> = new Map();

    create(name: string, email: string): User {
        const id = randomUUID();
        const user: User = { id, name, email };
        this.userStore.set(id, user);
        return user;
    }

    getById(id: string): User | undefined {
        return this.userStore.get(id);
    }

    getAll(): User[] {
        return Array.from(this.userStore.values());
    }

    update(id: string, name: string, email: string): User | undefined {
        const user = this.userStore.get(id);
        if (user) {
            user.name = name;
            user.email = email;
            return user;
        }
        return undefined;
    }

    delete(id: string): boolean {
        return this.userStore.delete(id);
    }
}

export const userService = new UserService();

import { randomUUID } from 'crypto';

export interface Project {
    id: string;
    name: string;
    description: string;
    memberIds: string[];
}

class ProjectService {
    private projectStore: Map<string, Project> = new Map();

    create(name: string, description: string, ownerId: string): Project {
        const id = randomUUID();
        const project: Project = {
            id,
            name,
            description,
            memberIds: [ownerId]
        };
        this.projectStore.set(id, project);
        return project;
    }

    getById(id: string): Project | undefined {
        return this.projectStore.get(id);
    }

    getAll(): Project[] {
        return Array.from(this.projectStore.values());
    }

    update(id: string, name: string, description: string): Project | undefined {
        const project = this.projectStore.get(id);
        if (project) {
            project.name = name;
            project.description = description;
            return project;
        }
        return undefined;
    }

    delete(id: string): boolean {
        return this.projectStore.delete(id);
    }

    addMember(id: string, memberId: string): Project | undefined {
        const project = this.projectStore.get(id);
        if (project && !project.memberIds.includes(memberId)) {
            project.memberIds.push(memberId);
            return project;
        }
        return undefined;
    }

    removeMember(id: string, memberId: string): Project | undefined {
        const project = this.projectStore.get(id);
        if (project) {
            project.memberIds = project.memberIds.filter(id => id !== memberId);
            return project;
        }
        return undefined;
    }
}

export const projectService = new ProjectService();

import { randomUUID } from 'crypto';
import { eventBus } from '../event-bus';

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export interface Task {
    id: string;
    title: string;
    description: string;
    status: TaskStatus;
    assigneeId: string | null;
    projectId: string;
}

class TaskService {
    private taskStore: Map<string, Task> = new Map();

    create(title: string, description: string, projectId: string): Task {
        const id = randomUUID();
        const task: Task = {
            id,
            title,
            description,
            projectId,
            status: 'todo',
            assigneeId: null
        };
        this.taskStore.set(id, task);
        return task;
    }

    getById(id: string): Task | undefined {
        return this.taskStore.get(id);
    }

    getByProject(projectId: string): Task[] {
        return Array.from(this.taskStore.values()).filter(
            task => task.projectId === projectId
        );
    }

    update(id: string, title: string, description: string): Task | undefined {
        const task = this.taskStore.get(id);
        if (task) {
            task.title = title;
            task.description = description;
            return task;
        }
        return undefined;
    }

    delete(id: string): boolean {
        return this.taskStore.delete(id);
    }

    assign(id: string, assigneeId: string): Task | undefined {
        const task = this.taskStore.get(id);
        if (task) {
            task.assigneeId = assigneeId;
            eventBus.publish('task.assigned', {
                taskId: task.id,
                taskTitle: task.title,
                assigneeId: task.assigneeId,
            });
            return task;
        }
        return undefined;
    }

    changeStatus(id: string, newStatus: TaskStatus): Task | undefined {
        const task = this.taskStore.get(id);
        if (!task) {
            return undefined;
        }

        const oldStatus = task.status;
        const allowedTransitions: Record<TaskStatus, TaskStatus[]> = {
            todo: ['in-progress'],
            'in-progress': ['done'],
            done: [],
        };

        if (allowedTransitions[oldStatus].includes(newStatus)) {
            task.status = newStatus;
            eventBus.publish('task.statusChanged', {
                taskId: task.id,
                taskTitle: task.title,
                assigneeId: task.assigneeId,
                oldStatus,
                newStatus,
            });
            return task;
        }
        // Invalid transition
        return undefined;
    }
}

export const taskService = new TaskService();

import { randomUUID } from 'crypto';
import { eventBus } from '../event-bus';

export interface Comment {
    id: string;
    taskId: string;
    authorId: string;
    body: string;
    createdAt: string;
}

class CommentService {
    private commentStore: Map<string, Comment> = new Map();

    create(
        taskId: string,
        authorId: string,
        body: string,
        // The router is expected to fetch and provide these details
        taskTitle: string,
        authorName: string
    ): Comment {
        const id = randomUUID();
        const createdAt = new Date().toISOString();
        const comment: Comment = { id, taskId, authorId, body, createdAt };
        this.commentStore.set(id, comment);

        eventBus.publish('comment.added', {
            commentId: comment.id,
            taskId: comment.taskId,
            taskTitle: taskTitle,
            authorId: comment.authorId,
            authorName: authorName,
        });

        return comment;
    }

    getById(id: string): Comment | undefined {
        return this.commentStore.get(id);
    }

    getByTask(taskId: string): Comment[] {
        return Array.from(this.commentStore.values()).filter(
            comment => comment.taskId === taskId
        );
    }

    delete(id: string): boolean {
        return this.commentStore.delete(id);
    }
}

export const commentService = new CommentService();
